BRIDGE_GATE_A_MANIFEST_SHA256="$(printf 'a%.0s' {1..64})" BRIDGE_RELEASE_BUNDLE="$T/bundle" BRIDGE_CANISTER_INIT_FILE="$T/malicious-init.json" BRIDGE_CONSTRUCTOR_ARGS_FILE="$T/malicious-constructors.json" BRIDGE_DEPLOYER_ADDRESS=0x4444444444444444444444444444444444444444 BRIDGE_DFX_IDENTITY=production "$DRIVER_ROOT/scripts/production-deploy-driver.sh"
python3 - "$TRACE" <<'PY'
import sys
s=open(sys.argv[1]).read(); required=['BridgeTimelockController','src/Bridge.sol','cast call','dfx canister install','dfx canister call']; pos=-1
